def _tokenize(text):
    """Split text on unquoted SEP into fields of (char, quoted) tokens.

    Quote characters that open or close a quoted part are not kept. Inside quotes,
    two QUOTE characters in a row become one QUOTE token.
    """
    fields, field, quoted, i = [], [], False, 0
    while i < len(text):
        ch = text[i]
        if ch == QUOTE:
            if quoted and i + 1 < len(text) and text[i + 1] == QUOTE:
                field.append((QUOTE, True))
                i += 2
                continue
            quoted = not quoted
        elif ch == SEP and not quoted:
            fields.append(field)
            field = []
        else:
            field.append((ch, quoted))
        i += 1
    if quoted:
        raise ValueError(f"unclosed quote in {text!r}")
    fields.append(field)
    return fields


def _text(tokens):
    """Join tokens, dropping unquoted whitespace at both ends."""
    start, end = 0, len(tokens)
    while start < end and not tokens[start][1] and tokens[start][0].isspace():
        start += 1
    while end > start and not tokens[end - 1][1] and tokens[end - 1][0].isspace():
        end -= 1
    return "".join(ch for ch, _ in tokens[start:end])


def parse_fields(text):
    """Parse a line like name=Ann| note="hi| there" into a dict of strings.

    Fields are separated by SEP. Whitespace around keys and around unquoted values is
    ignored. A value may be wrapped in QUOTE characters; inside quotes, SEP and '='
    are ordinary characters, whitespace is kept, and two QUOTE characters in a row
    stand for one QUOTE character. Empty fields, such as one after a trailing SEP,
    are skipped, so a blank line gives {}. A field without '=', an empty key, a
    quote that is never closed, or a key that appears twice raises ValueError.
    """
    result = {}
    for field in _tokenize(text):
        if all(not quoted and ch.isspace() for ch, quoted in field):
            continue
        eq = next((i for i, (ch, quoted) in enumerate(field) if ch == "=" and not quoted), None)
        if eq is None:
            raise ValueError(f"field without '=': {_text(field)!r}")
        key = _text(field[:eq])
        if not key:
            raise ValueError(f"empty key in {_text(field)!r}")
        if key in result:
            raise ValueError(f"duplicate key {key!r}")
        result[key] = _text(field[eq + 1:])
    return result

